package com.citacloud.springboot.contacloud.app.services;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import java.util.UUID;@Service public class ConteoFisicoNumeroService{private final JdbcTemplate jdbc;public ConteoFisicoNumeroService(JdbcTemplate j){jdbc=j;}public String siguiente(UUID t,UUID e){Long n=jdbc.queryForObject("INSERT INTO inventory_physical_count_sequence(tenant_id,empresa_id,last_number) VALUES(?,?,1) ON CONFLICT(tenant_id,empresa_id) DO UPDATE SET last_number=inventory_physical_count_sequence.last_number+1 RETURNING last_number",Long.class,t,e);return "CON-"+String.format("%06d",n);}}
